import XCTest
import CryptoKit
@testable import FlagshipCore

/// Pins the Swift port to packages/protocol/test-vectors/account-key-rotation/vectors.json
/// (generated by tools/account-key-rotation-vectors.ts): every canonical form, every hop,
/// companion, delivery, plaintext, kept-device and derived-key case, both seals re-made byte for
/// byte, and the vectors' Ed25519 signatures (CryptoKit signs randomized, so ours round-trip).
final class AccountKeyRotationVectorTests: XCTestCase {
    typealias A = AccountKeyRotation

    private func vectors() throws -> [String: Any] {
        var dir = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        for _ in 0..<14 {
            let url = dir.appendingPathComponent("packages/protocol/test-vectors/account-key-rotation/vectors.json")
            if FileManager.default.fileExists(atPath: url.path) {
                return try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
            }
            dir = dir.deletingLastPathComponent()
        }
        throw XCTSkip("account-key-rotation vectors not found above \(#filePath)")
    }

    private func o(_ v: Any?) -> [String: Any] { v as! [String: Any] }
    private func s(_ v: Any?) -> String { v as! String }
    private func i64(_ v: Any?) -> Int64 { (v as! NSNumber).int64Value }
    private func b(_ v: Any?) -> [UInt8] { PqBin.unhex(v as! String)! }

    private func rotation(_ f: [String: Any]) -> A.Rotation {
        A.Rotation(username: s(f["username"]), fromEpoch: i64(f["fromEpoch"]), toEpoch: i64(f["toEpoch"]),
                   oldIrkPubHex: s(f["oldIrkPubHex"]), newIrkPubHex: s(f["newIrkPubHex"]), newIrkScheme: s(f["newIrkScheme"]),
                   oldAidPubHex: s(f["oldAidPubHex"]), newAidPubHex: s(f["newAidPubHex"]), adminRootPubHex: s(f["adminRootPubHex"]),
                   removedDeviceIds: f["removedDeviceIds"] as! [String], keptDevicesDigestHex: s(f["keptDevicesDigestHex"]),
                   recoveryRecordDigestHex: f["recoveryRecordDigestHex"] as? String, nonceHex: s(f["nonceHex"]), issuedAt: i64(f["issuedAt"]))
    }
    private func sigs(_ f: [String: Any]) -> A.Signatures {
        A.Signatures(adminRootSignatureHex: s(f["adminRootSignatureHex"]), newIrkSignatureHex: s(f["newIrkSignatureHex"]),
                     newAidSignatureHex: s(f["newAidSignatureHex"]))
    }
    private func state(_ f: [String: Any]) -> A.KeyState {
        A.KeyState(username: s(f["username"]), epoch: i64(f["epoch"]), irkPubHex: s(f["irkPubHex"]),
                   aidPubHex: f["aidPubHex"] as? String, adminRootPubHex: s(f["adminRootPubHex"]))
    }
    private func delivery(_ f: [String: Any]) -> A.Delivery {
        A.Delivery(username: s(f["username"]), toEpoch: i64(f["toEpoch"]), deviceId: s(f["deviceId"]), devicePubHex: s(f["devicePubHex"]),
                   rotationDigestHex: s(f["rotationDigestHex"]), sealedDigestHex: s(f["sealedDigestHex"]), issuedAt: i64(f["issuedAt"]))
    }
    private func kept(_ v: Any?) -> [A.KeptDevice] {
        (v as! [[String: Any]]).map { A.KeptDevice(deviceId: s($0["deviceId"]), devicePubHex: s($0["devicePubHex"])) }
    }
    private func dev(_ v: Any?) -> A.KeptDevice { let d = o(v); return A.KeptDevice(deviceId: s(d["deviceId"]), devicePubHex: s(d["devicePubHex"])) }
    private func want(_ e: Any?) -> String { let e = o(e); return (e["ok"] as! Bool) ? "ok" : s(e["code"]) }
    private func code(_ f: () throws -> Void) -> String {
        do { try f(); return "ok" } catch let e as A.Failure { return e.code } catch let e as PqTrustError { return e.code } catch { return "other:\(error)" }
    }
    private func policy(_ p: Any?) -> PolicyState {
        let p = o(p)
        var st = AssurancePolicy.legacyState(PolicyScope(kind: .installation, id: "home.alice.flagship.services"))
        st.profile = AssuranceProfile(rawValue: s(p["profile"]))!
        st.rollout = RolloutState(rawValue: s(p["rollout"]))!
        return st
    }
    private func verified(_ v: [String: Any], _ name: Any?) throws -> VerifiedPqKeyBinding? {
        guard let name = name as? String else { return nil }
        let w = o(o(v["bindings"])[name])
        return try PqTrust.verifyPqKeyBinding(w as Any?, PqBindingExpectation(
            role: s(w["role"]), subjectId: s(w["subjectId"]), ed25519PubHex: s(w["ed25519PubHex"]), now: i64(v["now"])))
    }
    private func utf8(_ b: [UInt8]) -> String { String(decoding: b, as: UTF8.self) }

    func testCanonicalForms() throws {
        let v = try vectors()
        let rot = o(v["rotation"]), r = rotation(o(rot["fields"]))
        XCTAssertEqual(utf8(try A.canonical(r)), s(rot["canonical"]))
        XCTAssertEqual(try A.digestHex(r), s(rot["digestHex"]))
        let k = o(v["keptDevices"])
        XCTAssertEqual(try A.keptDevicesLines(kept(k["list"])), s(k["lines"]))
        XCTAssertEqual(try A.keptDevicesDigestHex(kept(k["list"])), s(k["digestHex"]))
        let pq = o(v["pq"]), nb = o(o(v["bindings"])["newIrk"])
        XCTAssertEqual(PqAuthorityRecords.bindingKeyIdHex(ed25519PubHex: s(nb["ed25519PubHex"]), mldsaPubHex: s(nb["mldsaPubHex"])), s(pq["newIrkKeyIdHex"]))
        XCTAssertEqual(utf8(try A.canonicalV2(r, newIrkKeyIdHex: s(pq["newIrkKeyIdHex"]))), s(pq["canonicalV2"]))
        for kind in ["xwing", "ed25519"] {
            let d = o(o(v["delivery"])[kind])
            XCTAssertEqual(utf8(try A.canonical(delivery(o(d["delivery"])))), s(d["canonical"]))
        }
        let dkr = o(v["deviceKeyRotate"]), df = o(dkr["fields"])
        XCTAssertEqual(utf8(try A.canonicalDeviceKeyRotate(username: s(df["username"]), deviceId: s(df["deviceId"]), oldDevicePubHex: s(df["oldDevicePubHex"]),
                                                           newDevicePubHex: s(df["newDevicePubHex"]), issuedAt: i64(df["issuedAt"]))), s(dkr["canonical"]))
        let drk = o(v["deviceReceiveKey"]), rf = o(drk["fields"])
        XCTAssertEqual(utf8(try A.canonicalDeviceReceiveKey(username: s(rf["username"]), deviceId: s(rf["deviceId"]), devicePubHex: s(rf["devicePubHex"]),
                                                            xwingPubHex: s(rf["xwingPubHex"]), issuedAt: i64(rf["issuedAt"]))), s(drk["canonical"]))
        let keys = o(v["keys"])
        XCTAssertEqual(PqBin.hex(A.irkSeed(umk: b(keys["oldUmkHex"]), scheme: .web, version: 2)), s(o(keys["oldIrk"])["seedHex"]))
        XCTAssertEqual(PqBin.hex(A.irkSeed(umk: b(keys["newUmkHex"]), scheme: .ios)), s(o(keys["newIrk"])["seedHex"]))
        XCTAssertEqual(PqBin.hex(A.aidSeed(umk: b(keys["newUmkHex"]))), s(o(keys["newAid"])["seedHex"]))
    }

    func testFollowUpsVerify() throws {
        let v = try vectors()
        let keys = o(v["keys"]), admin = s(o(keys["adminRoot"])["pubHex"]), other = s(o(keys["other"])["pubHex"])
        let signerPub = { (n: String) in n == "newIrk" ? self.s(self.o(keys["newIrk"])["pubHex"]) : admin }
        let cgk = o(v["cgkRekey"]), cf = o(cgk["fields"])
        let cgkBytes = { try A.canonicalCgkRekey(serverDomain: self.s(cf["serverDomain"]), toEpoch: self.i64(cf["toEpoch"]), sealedHex: self.s(cf["sealedHex"]), issuedAt: self.i64(cf["issuedAt"])) }
        XCTAssertEqual(utf8(try cgkBytes()), s(cgk["canonical"]))
        XCTAssertTrue(A.verifyRekey(cgkBytes, signatureHex: s(cgk["signatureHex"]), signerPubHex: signerPub(s(cgk["signer"]))))
        XCTAssertFalse(A.verifyRekey(cgkBytes, signatureHex: s(cgk["signatureHex"]), signerPubHex: other))
        let swk = o(v["swkRekey"]), sf = o(swk["fields"])
        let swkBytes = { try A.canonicalSwkRekey(serverDomain: self.s(sf["serverDomain"]), toEpoch: self.i64(sf["toEpoch"]), oldSwkCommitHex: self.s(sf["oldSwkCommitHex"]),
                                                 sealedHex: self.s(sf["sealedHex"]), issuedAt: self.i64(sf["issuedAt"])) }
        XCTAssertEqual(utf8(try swkBytes()), s(swk["canonical"]))
        XCTAssertTrue(A.verifyRekey(swkBytes, signatureHex: s(swk["signatureHex"]), signerPubHex: signerPub(s(swk["signer"]))))
        let luks = o(v["luksRekeyConfirm"]), lf = o(luks["fields"])
        let luksBytes = { try A.canonicalLuksRekeyConfirm(serverDomain: self.s(lf["serverDomain"]), toEpoch: self.i64(lf["toEpoch"]),
                                                          sealedKeyDigestHex: self.s(lf["sealedKeyDigestHex"]), issuedAt: self.i64(lf["issuedAt"])) }
        XCTAssertEqual(utf8(try luksBytes()), s(luks["canonical"]))
        XCTAssertTrue(A.verifyRekey(luksBytes, signatureHex: s(luks["signatureHex"]), signerPubHex: signerPub(s(luks["signer"]))))
        XCTAssertFalse(A.verifyRekey(luksBytes, signatureHex: s(luks["signatureHex"]), signerPubHex: admin))
        XCTAssertThrowsError(try A.canonicalCgkRekey(serverDomain: "Home.example", toEpoch: 1, sealedHex: "ab", issuedAt: 1))

        let dkr = o(v["deviceKeyRotate"]), df = o(dkr["fields"])
        let dk = { (root: String, newPub: String) in
            A.verifyDeviceKeyRotate(username: self.s(df["username"]), deviceId: self.s(df["deviceId"]), oldDevicePubHex: self.s(df["oldDevicePubHex"]),
                                    newDevicePubHex: newPub, issuedAt: self.i64(df["issuedAt"]), newKeySignatureHex: self.s(dkr["newKeySignatureHex"]),
                                    adminRootSignatureHex: self.s(dkr["adminRootSignatureHex"]), adminRootPubHex: root)
        }
        XCTAssertTrue(dk(admin, s(df["newDevicePubHex"])))
        XCTAssertFalse(dk(other, s(df["newDevicePubHex"])))
        XCTAssertFalse(dk(admin, s(df["oldDevicePubHex"])))
        let drk = o(v["deviceReceiveKey"]), rf = o(drk["fields"])
        XCTAssertTrue(A.verifyDeviceReceiveKey(username: s(rf["username"]), deviceId: s(rf["deviceId"]), devicePubHex: s(rf["devicePubHex"]),
                                               xwingPubHex: s(rf["xwingPubHex"]), issuedAt: i64(rf["issuedAt"]), signatureHex: s(drk["signatureHex"])))
        XCTAssertFalse(A.verifyDeviceReceiveKey(username: s(rf["username"]), deviceId: s(o(keys["deviceIds"])["c"]), devicePubHex: s(rf["devicePubHex"]),
                                                xwingPubHex: s(rf["xwingPubHex"]), issuedAt: i64(rf["issuedAt"]), signatureHex: s(drk["signatureHex"])))
    }

    func testSignsRoundTrip() throws {
        let v = try vectors()
        let keys = o(v["keys"]), r = rotation(o(o(v["rotation"])["fields"]))
        let sg = try A.sign(r, adminRoot: try A.seedSigner(b(o(keys["adminRoot"])["seedHex"])),
                            newIrk: try A.seedSigner(b(o(keys["newIrk"])["seedHex"])), newAid: try A.seedSigner(b(o(keys["newAid"])["seedHex"])))
        XCTAssertNoThrow(try A.verify(r, signatures: sg, state: state(o(v["chainStart"]))))
        let root = o(keys["adminRoot"])
        let secret = b(root["seedHex"]) + b(root["mldsaSeedHex"])
        let nb = try PqTrust.pqKeyBindingFromWire(o(v["bindings"])["newIrk"])
        let c = try A.signPq(r, newIrkBinding: nb) { purpose, payload in
            try PqHybrid.hybridSign(secretKey: secret, purpose: purpose, payload: payload, deterministic: true)
        }
        let want = o(o(v["pqSignatures"])["adminRoot"])
        XCTAssertEqual(String(s(o(c["signature"])["signature"]).dropFirst(128)), String(s(want["signature"]).dropFirst(128)))
        _ = try A.verifyPq(r, pq: c, adminRootBinding: try verified(v, "adminRoot"), policy: policy(["profile": "strict", "rollout": "enforced"]), now: i64(v["now"]))
    }

    func testHopCases() throws {
        let v = try vectors()
        for case let c as [String: Any] in v["hopCases"] as! [Any] {
            let got = code { try A.verify(rotation(o(c["rotation"])), signatures: sigs(o(c["signatures"])), state: state(o(c["state"]))) }
            XCTAssertEqual(got, want(c["expect"]), s(c["name"]))
        }
    }

    func testPqCases() throws {
        let v = try vectors()
        let r = rotation(o(o(v["rotation"])["fields"]))
        for case let c as [String: Any] in v["pqCases"] as! [Any] {
            var pq: Any? = nil
            if let sig = c["signature"] as? String, let bind = c["binding"] as? String {
                pq = ["signature": o(v["pqSignatures"])[sig]!, "newIrkBinding": o(v["bindings"])[bind]!]
            }
            let got = code { _ = try A.verifyPq(r, pq: pq, adminRootBinding: try verified(v, c["adminRootBinding"]), policy: policy(c["policy"]), now: i64(v["now"])) }
            XCTAssertEqual(got, want(c["expect"]), s(c["name"]))
        }
    }

    func testSealsReproduceByteForByte() throws {
        let v = try vectors()
        let keys = o(v["keys"]), r = rotation(o(o(v["rotation"])["fields"])), ids = o(keys["deviceIds"])
        let recv = try PqHybrid.hybridSealKeygen(seed: b(o(keys["bReceive"])["seedHex"]))
        XCTAssertEqual(PqBin.hex(recv.publicKey), s(o(keys["bReceive"])["pubHex"]))
        let x = o(o(v["delivery"])["xwing"])
        let sealed = try A.sealXWing(r, deviceId: s(ids["b"]), plaintext: b(x["plaintextHex"]), receiveKey: recv.publicKey,
                                     issuedAt: i64(x["issuedAt"]), randomness: b(x["randomnessHex"]))
        XCTAssertEqual(PqBin.hex(sealed), s(x["sealedHex"]))
        let e = o(o(v["delivery"])["ed25519"])
        let sealedC = try A.sealEd25519(plaintext: b(e["plaintextHex"]), devicePub: b(o(o(keys["devices"])["c"])["pubHex"]),
                                        ephPriv: b(e["ephPrivHex"]), nonce: b(e["nonceHex"]))
        XCTAssertEqual(PqBin.hex(sealedC), s(e["sealedHex"]))
        let built = try A.buildDelivery(r, deviceId: s(ids["b"]), devicePubHex: s(o(o(keys["devices"])["b"])["pubHex"]), sealed: sealed,
                                        issuedAt: i64(x["issuedAt"]), adminRoot: try A.seedSigner(b(o(keys["adminRoot"])["seedHex"])))
        XCTAssertEqual(built.delivery, delivery(o(x["delivery"])))
        XCTAssertTrue(A.verifyEd(built.signatureHex, try A.canonical(built.delivery), r.adminRootPubHex))
        XCTAssertTrue(A.verifyEd(s(x["signatureHex"]), try A.canonical(built.delivery), r.adminRootPubHex))
    }

    func testDeliveryCases() throws {
        let v = try vectors()
        let newUmk = s(o(v["keys"])["newUmkHex"])
        for case let c as [String: Any] in v["deliveryCases"] as! [Any] {
            var opened: A.Plaintext?
            let got = code {
                opened = try A.open(rotation(o(c["rotation"])), delivery: delivery(o(c["delivery"])), signatureHex: s(c["signatureHex"]),
                                    sealed: b(c["sealedHex"]), kind: A.SealKind(rawValue: s(c["kind"]))!, selfDevice: dev(c["self"]), secret: b(c["secretHex"]))
            }
            XCTAssertEqual(got, want(c["expect"]), s(c["name"]))
            if got == "ok" { XCTAssertEqual(PqBin.hex(opened!.umk), newUmk) }
        }
    }

    func testPlaintextKeptAndDerivedCases() throws {
        let v = try vectors()
        for case let c as [String: Any] in v["plaintextCases"] as! [Any] {
            var p: A.Plaintext?
            let got = code { p = try A.decodePlaintext(b(c["hex"])) }
            XCTAssertEqual(got, want(c["expect"]), s(c["name"]))
            if got == "ok", let p {
                let e = o(c["expect"])
                XCTAssertEqual(PqBin.hex(p.umk), s(e["umkHex"]))
                XCTAssertEqual(p.irkScheme.rawValue, s(e["irkScheme"]))
                XCTAssertEqual(p.adminRootSeed.map(PqBin.hex), e["adminRootSeedHex"] as? String)
                XCTAssertEqual(PqBin.hex(try A.encodePlaintext(p)), s(c["hex"]))
            }
        }
        let r = rotation(o(o(v["rotation"])["fields"]))
        for case let c as [String: Any] in v["keptCases"] as! [Any] {
            XCTAssertEqual(code { try A.verifyKept(r, kept: kept(c["kept"]), selfDevice: dev(c["self"])) }, want(c["expect"]), s(c["name"]))
        }
        for case let c as [String: Any] in v["derivedCases"] as! [Any] {
            XCTAssertEqual(A.deviceKeyIsUmkDerived(umk: b(c["umkHex"]), accountName: s(c["username"]), deviceId: s(c["deviceId"]),
                                                   devicePubHex: s(c["devicePubHex"])), c["derived"] as! Bool, s(c["name"]))
        }
    }
}
